def can_form_equal_teams(scores):
    total_score = sum(scores)
    if total_score % 2 != 0:
        return "NO"

    target_score = total_score // 2
    n = len(scores)

    # dp[i][j] will be True if a subset of the first i elements has a sum of j
    dp = [[False] * (target_score + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(target_score + 1):
            if j >= scores[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - scores[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Check if we can form two subsets with equal sum
    if dp[n][target_score]:
        return "YES"
    else:
        return "NO"

