def can_form_equal_teams(scores):
    total_score = sum(scores)

    # If the total score is odd, it's impossible to split into two equal parts
    if total_score % 2 != 0:
        return "NO"

    target_score = total_score // 2

    # Use a set to track possible sums with subsets of the scores
    possible_sums = {0}

    for score in scores:
        new_sums = set()
        for current_sum in possible_sums:
            new_sum = current_sum + score
            if new_sum == target_score:
                return "YES"
            if new_sum < target_score:
                new_sums.add(new_sum)
        possible_sums.update(new_sums)

    return "NO"

